static java.util.OptionalInt bookId(String path) {
if(!path.startsWith("/books/")) return java.util.OptionalInt.empty();
String s=path.substring(7);
if(s.isEmpty()||s.length()>6||s.charAt(0)<'1'||s.charAt(0)>'9') return java.util.OptionalInt.empty();
int id=0;
for(int i=0;i<s.length();i++){char c=s.charAt(i);if(c<'0'||c>'9') return java.util.OptionalInt.empty();id=id*10+c-'0';}
return java.util.OptionalInt.of(id);
}
}

