public class Main {

static java.util.Optional<String> rawQuery(String query,String key) {
String value=null; boolean found=false;
for(String part:query.split("&",-1)){
 if(part.isEmpty()) continue;
 int at=part.indexOf('=');String name=at<0?part:part.substring(0,at);
 if(!name.equals(key)) continue;
 if(found) throw new IllegalArgumentException("duplicate");
 found=true;value=at<0?"":part.substring(at+1);
}
return found?java.util.Optional.of(value):java.util.Optional.empty();
}
}

