public class Main {
record Book(int version,String title) {}
static int updateTitle(java.util.concurrent.ConcurrentMap<Integer,Book> rows,int id,int expected,String title) {
if(title.isBlank()) return 400;
Book old=rows.get(id);if(old==null) return 404;
