public class Main {
@FunctionalInterface interface SqlWork {void run() throws java.sql.SQLException;}
static void transaction(java.sql.Connection c,SqlWork work) throws java.sql.SQLException {
if(!c.getAutoCommit()) throw new java.sql.SQLException("nested");
c.setAutoCommit(false);
